/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

/*--------------------------------------------------------------------------*/                 

void process_state_start( Process_Node* process )
{
    process->start_done = FALSE ;     
    
    process->tmr = PROCESS_START_GUARD_TIMEOUT ; 
}

/*--------------------------------------------------------------------------*/                 

Boolean process_state_exec( Process_Node* process )
{
    if( !process->start_done )
    {
        if( !(--process->tmr) )
        {            
            process->tmr = process->timeout ;   
            
            if( process->start )
            {
                (process->start)((void*)process) ; 
            }

            process->start_done = TRUE  ; 
         }

         return FALSE ; 
     }           
             
    
    return (!(process->tmr--)&&(!process->no_timeout)) || ( (process->exec)?((process->exec)((void *)process)):FALSE ) ; 
}

/*--------------------------------------------------------------------------*/                 

void process_state_stop( Process_Node* process )
{
    if( process->start_done && process->stop )
    {
        (process->stop)((void *)process) ; 
    }

    process->start_done = FALSE ; 
}

